interface TransactionFormLayoutProps {
  title: string;
  badge?: string;
  category?: string;
  icon: React.ElementType;
  iconBg?: string;
  description: string;
  breadcrumbs: Array<{ label: string; onClick?: () => void }>;
  onBack: () => void;
  backLabel: string;
  onReset?: () => void;
  onSave?: (e?: any) => void | Promise<void>;
  saveLabel?: string;
  saveIcon?: React.ElementType;
  isSubmitting?: boolean;
  isSaveDisabled?: boolean;
  saveButton?: React.ReactNode;
  headerActions?: React.ReactNode;
  children: React.ReactNode;
}

function TransactionFormLayout({
  title,
  badge,
  category,
  icon: Icon,
  iconBg,
  description,
  breadcrumbs,
  onBack,
  backLabel,
  onReset,
  onSave,
  saveLabel = "Save Record",
  saveIcon: SaveIcon,
  isSubmitting = false,
  isSaveDisabled = false,
  saveButton,
  headerActions,
  children
}: TransactionFormLayoutProps) {
  useEffect(() => {
    if (typeof window !== "undefined") {
      window.scrollTo({ top: 0, left: 0, behavior: "instant" });
      document.documentElement.scrollTop = 0;
      document.body.scrollTop = 0;
      const mainEl = document.querySelector("main");
      if (mainEl) mainEl.scrollTop = 0;
    }
  }, []);

  return (
    <div className="w-full flex-1 flex flex-col space-y-8 animate-in fade-in duration-200">
      {/* Top Navigation & Action Header */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 border-b border-border pb-6">
        <div className="space-y-1.5">
          <div className="flex items-center gap-2 flex-wrap">
            <AppButton
              variant="ghost"
              size="sm"
              onClick={onBack}
              className="text-xs h-8 px-2.5 gap-1.5 text-muted-foreground hover:text-foreground font-semibold"
            >
              <ArrowLeft className="h-4 w-4" />
              <span>{backLabel}</span>
            </AppButton>
            {breadcrumbs.map((bc, idx) => (
              <React.Fragment key={idx}>
                <span className="text-border text-xs">/</span>
                {bc.onClick ? (
                  <button
                    type="button"
                    onClick={bc.onClick}
                    className="text-xs text-muted-foreground hover:text-foreground font-medium transition-colors"
                  >
                    {bc.label}
                  </button>
                ) : (
                  <span className="text-xs text-muted-foreground font-medium">{bc.label}</span>
                )}
              </React.Fragment>
            ))}
          </div>
          <div className="flex items-center gap-3 pt-1">
            <div className={`h-11 w-11 rounded-xl flex items-center justify-center border shrink-0 ${iconBg || "bg-accent-soft text-theme-btn-primary border-theme-btn-primary/20"}`}>
              <Icon className="h-6 w-6" />
            </div>
            <div>
              <h1 className="text-2xl font-bold tracking-tight text-foreground flex items-center gap-2.5 flex-wrap">
                <span>{title}</span>
                {badge && (
                  <span className="text-xs font-semibold px-2.5 py-0.5 rounded-full bg-accent-soft text-theme-btn-primary border border-theme-btn-primary/20">
                    {badge}
                  </span>
                )}
              </h1>
            </div>
          </div>
        </div>

        {/* Top Actions */}
        <div className="flex items-center gap-2.5 flex-wrap self-end md:self-center">
          {headerActions}
          <AppButton
            type="button"
            variant="outline"
            size="sm"
            onClick={onBack}
            className="text-xs h-9 px-4 font-semibold"
          >
            Cancel
          </AppButton>
          {onReset && (
            <AppButton
              type="button"
              variant="ghost"
              size="sm"
              onClick={onReset}
              className="text-xs h-9 text-muted-foreground hover:text-foreground"
            >
              <RotateCcw className="h-3.5 w-3.5 mr-1" />
              Reset form
            </AppButton>
          )}
          {saveButton ? (
            saveButton
          ) : onSave ? (
            <AppButton
              type="button"
              variant="primary"
              size="sm"
              disabled={isSubmitting || isSaveDisabled}
              onClick={(e) => onSave?.(e)}
              className="bg-theme-btn-primary hover:bg-theme-btn-primary-secondary text-theme-btn-primary-text text-xs h-9 font-semibold gap-1.5 shadow-xs px-5"
            >
              {isSubmitting ? (
                <RefreshCw className="h-3.5 w-3.5 animate-spin" />
              ) : SaveIcon ? (
                <SaveIcon className="h-3.5 w-3.5" />
              ) : (
                <Save className="h-3.5 w-3.5" />
              )}
              <span>{saveLabel}</span>
            </AppButton>
          ) : null}
        </div>
      </div>

      {/* Transaction Canvas */}
      <div className="space-y-6">
        {children}
      </div>

      {/* Bottom Back & Action Flow */}
      <div className="flex flex-col sm:flex-row items-center justify-between gap-4 border-t border-border pt-6 pb-12">
        <AppButton
          type="button"
          variant="outline"
          size="sm"
          onClick={onBack}
          className="text-xs h-9 px-4 gap-1.5 font-semibold"
        >
          <ArrowLeft className="h-4 w-4" />
          <span>{backLabel}</span>
        </AppButton>

        <div className="flex items-center gap-2.5 flex-wrap">
          {headerActions}
          <AppButton
            type="button"
            variant="outline"
            size="sm"
            onClick={onBack}
            className="text-xs h-9 px-4 font-semibold"
          >
            Cancel
          </AppButton>
          {onReset && (
            <AppButton
              type="button"
              variant="ghost"
              size="sm"
              onClick={onReset}
              className="text-xs h-9 text-muted-foreground hover:text-foreground"
            >
              <RotateCcw className="h-3.5 w-3.5 mr-1" />
              Reset form
            </AppButton>
          )}
          {saveButton ? (
            saveButton
          ) : onSave ? (
            <AppButton
              type="button"
              variant="primary"
              size="sm"
              disabled={isSubmitting || isSaveDisabled}
              onClick={(e) => onSave?.(e)}
              className="bg-theme-btn-primary hover:bg-theme-btn-primary-secondary text-theme-btn-primary-text text-xs h-9 font-semibold gap-1.5 shadow-xs px-5"
            >
              {isSubmitting ? (
                <RefreshCw className="h-3.5 w-3.5 animate-spin" />
              ) : SaveIcon ? (
                <SaveIcon className="h-3.5 w-3.5" />
              ) : (
                <Save className="h-3.5 w-3.5" />
              )}
              <span>{saveLabel}</span>
            </AppButton>
          ) : null}
        </div>
      </div>
    </div>
  );
}

