  // Dynamic Expiry Badge Helper
  const renderExpiryBadge = (days?: number | null) => {
    if (days === null || days === undefined) return null;
    if (days < 0) {
      return (
        <span className="px-2 py-0.5 rounded text-xs font-semibold bg-danger-soft text-danger-text border border-danger/30 inline-flex items-center gap-1">
          <span className="h-1.5 w-1.5 rounded-full bg-danger animate-pulse" />
          <span>Expired {Math.abs(days)}d ago</span>
        </span>
      );
    }
    if (days === 0) {
      return (
        <span className="px-2 py-0.5 rounded text-xs font-semibold bg-warning-soft text-warning-text border border-warning/30 inline-flex items-center gap-1">
          <span className="h-1.5 w-1.5 rounded-full bg-warning" />
          <span>Expires today</span>
        </span>
      );
    }
    if (days <= 30) {
      return (
        <span className="px-2 py-0.5 rounded text-xs font-semibold bg-warning-soft text-warning-text border border-warning/30 inline-flex items-center gap-1">
          <span className="h-1.5 w-1.5 rounded-full bg-warning" />
          <span>Expires in {days}d</span>
        </span>
      );
    }
    return (
      <span className="px-2 py-0.5 rounded text-xs font-semibold bg-success-soft text-success-text border border-success/30 inline-flex items-center gap-1">
        <span className="h-1.5 w-1.5 rounded-full bg-success" />
        <span>Expires in {days}d</span>
      </span>
    );
  };

  // Authentic Indian High Security Registration Plate (HSRP) Badge with Type-Based Color Conventions
  const renderHsrpPlate = (
    plateNumber?: string,
    vehicleOrFuel?: { fuel_type?: string; category?: string } | string,
    categoryOverride?: string
  ) => {
    if (!plateNumber) return <span className="text-muted-foreground">—</span>;

    // Resolve authoritative fuel type & category from arguments or current vehicle dataset
    let fuelType: string | null | undefined;
    let vehicleCat: string | null | undefined;

    if (vehicleOrFuel && typeof vehicleOrFuel === "object") {
      fuelType = vehicleOrFuel.fuel_type;
      vehicleCat = vehicleOrFuel.category;
    } else if (typeof vehicleOrFuel === "string") {
      fuelType = vehicleOrFuel;
      vehicleCat = categoryOverride;
    }

    if (!fuelType && vehicles && vehicles.length > 0) {
      const cleanPlate = plateNumber.replace(/[^A-Za-z0-9]/g, "").toUpperCase();
      const matched = vehicles.find((v) => v.registration_number?.replace(/[^A-Za-z0-9]/g, "").toUpperCase() === cleanPlate);
      if (matched) {
        fuelType = matched.fuel_type;
        vehicleCat = matched.category;
      }
    }

    const isEv = fuelType ? isElectricFuel(fuelType) : false;
    const isCommercial = vehicleCat ? /commercial|taxi|transport|goods|carrier|bus|truck/i.test(vehicleCat) : false;

    // MoRTH Indian High Security Registration Plate (HSRP) Standards:
    // 1. Private EV: Green background (#0B6623) + White alphanumeric characters
    // 2. Commercial EV: Green background (#0B6623) + Yellow alphanumeric characters (#FACC15)
    // 3. Commercial Non-EV: Yellow background (#FACC15) + Black alphanumeric characters (#020617)
    // 4. Private Non-EV (Default): White background (#FFFFFF) + Black alphanumeric characters (#020617)
    let bgClass = "bg-surface";
    let textClass = "text-foreground";
    let inlineStyle: React.CSSProperties = {};

    if (isEv && isCommercial) {
      // ui-audit-ignore-next-line HSRP license plate standard
    inlineStyle = { backgroundColor: "#0b6623", color: "#facc15" };
      /* ui-audit-ignore HSRP license plate */ bgClass = "bg-success";
      /* ui-audit-ignore HSRP license plate */ textClass = "text-warning-text";
    } else if (isEv) {
      // ui-audit-ignore-next-line HSRP license plate standard
    inlineStyle = { backgroundColor: "#0b6623", color: "#ffffff" };
      /* ui-audit-ignore HSRP license plate */ bgClass = "bg-success";
      textClass = "text-white";
    } else if (isCommercial) {
      // ui-audit-ignore-next-line HSRP license plate standard
    inlineStyle = { backgroundColor: "#facc15", color: "#020617" };
      /* ui-audit-ignore HSRP license plate */ bgClass = "bg-warning-soft";
      textClass = "text-foreground";
    }

    return (
      <div 
        className="inline-flex items-stretch rounded-sm border-2 border-border shadow-xs overflow-hidden select-none"
        /* ui-audit-ignore-next-line HSRP border */ style={{ borderColor: "#0f172a" }}
      >
        {/* ui-audit-ignore-next-line HSRP IND blue strip */}
        {/* ui-audit-ignore-next-line HSRP IND strip */}
          <div className="bg-info px-1.5 py-0.5 flex flex-col items-center justify-center border-r border-info-border shrink-0">
          {/* ui-audit-ignore-next-line HSRP white text */}
          <span className="text-[11px] leading-none font-semibold tracking-normal !text-white select-none" style={{ color: "#ffffff", fontWeight: 900 }}>
            IND
          </span>
        </div>
        <div 
          className={`px-2 py-0.5 font-mono text-xs font-semibold ${bgClass} ${textClass}`}
          style={inlineStyle}
        >
          {plateNumber}
        </div>
      </div>
    );
  };

