  // Native CSV Export Utilities (Excel-compatible UTF-8 BOM)
  const exportVehiclesCSV = () => {
    if (!vehicles || vehicles.length === 0) {
      triggerToast("No vehicle records available to export");
      return;
    }
    const headers = [
      "Registration Plate",
      "Make",
      "Model",
      "Variant",
      "Category",
      "Fuel Type",
      "Current Odometer (km)",
      "Operational Status",
      "VIN / Chassis Number",
      "Engine Number",
      "RTO Office",
      "Registered Owner",
      "Insurance Vendor",
      "Policy Number",
      "Insurance Expiry Date",
      "PUC Expiry Date",
      "Fitness Expiry Date",
      "Basic Price (INR)",
      "GST Amount (INR)",
      "Cess Amount (INR)",
      "Ex-Showroom Price (INR)",
      "RTO Road Tax (INR)",
      "TCS (INR)",
      "Insurance Cost (INR)",
      "HSRP Fee (INR)",
      "FASTag Charges (INR)",
      "Accessories Cost (INR)",
      "Extended Warranty (INR)",
      "Other Charges (INR)",
      "Discount (INR)",
      "On-Road Capitalized Price (INR)",
      "HSRP Plate Fitted",
      "RSA Active"
    ];

    const escapeCSV = (val: any) => {
      if (val === null || val === undefined) return '""';
      const str = String(val).replace(/"/g, '""');
      return `"${str}"`;
    };

    const rows = vehicles.map((v) => [
      escapeCSV(v.registration_number),
      escapeCSV(v.make),
      escapeCSV(v.model),
      escapeCSV(v.variant || "Standard"),
      escapeCSV(v.category),
      escapeCSV(v.fuel_type),
      escapeCSV(v.odometer_km || 0),
      escapeCSV(v.status),
      escapeCSV(v.vin_chassis_number || ""),
      escapeCSV(v.engine_number || ""),
      escapeCSV(v.rto_office || ""),
      escapeCSV(v.registered_owner || ""),
      escapeCSV(v.insurance_vendor || ""),
      escapeCSV(v.insurance_policy_number || ""),
      escapeCSV(v.insurance_expiry_date ? v.insurance_expiry_date.split("T")[0] : ""),
      escapeCSV(v.puc_expiry_date ? v.puc_expiry_date.split("T")[0] : ""),
      escapeCSV(v.fitness_expiry_date ? v.fitness_expiry_date.split("T")[0] : ""),
      escapeCSV(v.basic_price || 0),
      escapeCSV(v.gst_amount || 0),
      escapeCSV(v.cess_amount || 0),
      escapeCSV(v.ex_showroom_price || v.purchase_price || 0),
      escapeCSV(v.rto_road_tax || 0),
      escapeCSV(v.tcs_amount || 0),
      escapeCSV(v.insurance_cost || 0),
      escapeCSV(v.hsrp_smart_card_fee || 0),
      escapeCSV(v.fastag_charges || 0),
      escapeCSV(v.accessories_cost || 0),
      escapeCSV(v.extended_warranty_cost || 0),
      escapeCSV(v.other_charges || 0),
      escapeCSV(v.discount_amount || 0),
      escapeCSV(v.on_road_price || v.purchase_price || v.purchase_cost || 0),
      escapeCSV(v.has_hsrp_plate ? "Yes" : "No"),
      escapeCSV(v.has_roadside_assistance ? "Yes" : "No")
    ].join(","));

    const csvContent = "\uFEFF" + [headers.join(","), ...rows].join("\r\n");
    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = `Fleet_Vehicles_Register_${new Date().toISOString().split("T")[0]}.csv`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
    triggerToast("Fleet vehicle register exported successfully!");
  };

